        return;
    if (m_project.tracks()[trackIndex].solo == solo)
        return;

    const drift::Project before = m_project;
    m_project.tracks()[trackIndex].solo = solo;
    pushProjectEdit(before, tr("Track solo"));
    finishEdit(solo ? tr("Track soloed") : tr("Track unsoloed"));
